const icsText = $input.first().json.data;

// Unfold continued lines (iCal lines fold with a leading space)
const unfolded = icsText
  .replace(/\r\n[ \t]/g, '')
  .replace(/\n[ \t]/g, '');

// Extract VEVENT blocks
const blocks = unfolded
  .split('BEGIN:VEVENT')
  .slice(1)
  .map(b => b.split('END:VEVENT')[0]);

// Convert UTC iCal datetime to Amsterdam local date and time
function parseDateTime(dtStr) {
  if (!dtStr) return { date: null, time: null };
  const clean = dtStr.replace('Z', '');
  const iso = `${clean.slice(0,4)}-${clean.slice(4,6)}-${clean.slice(6,8)}T${clean.slice(9,11)}:${clean.slice(11,13)}:${clean.slice(13,15) || '00'}Z`;
  const d = new Date(iso);
  return {
    date: d.toLocaleDateString('en-CA', { timeZone: 'Europe/Amsterdam' }),
    time: d.toLocaleTimeString('en-GB', { timeZone: 'Europe/Amsterdam', hour12: false })
  };
}

const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Amsterdam' });
const events = [];

for (const block of blocks) {
  const props = {};
  for (const line of block.trim().split(/\r?\n/)) {
    const i = line.indexOf(':');
    if (i === -1) continue;
    props[line.slice(0, i).split(';')[0]] = line.slice(i + 1);
  }

  const start = parseDateTime(props.DTSTART);
  const end = parseDateTime(props.DTEND);

  // Skip past events
  if (!start.date || start.date < today) continue;

  // Only set end_date if the event spans multiple days
  if (end.date === start.date) end.date = null;

  const desc = (props.DESCRIPTION || '').replace(/\\n/g, '\n');
  const urlMatch = desc.match(/https:\/\/luma\.com\/\S+/);
  const url = urlMatch ? urlMatch[0].split('\n')[0] : null;

  const geo = (props.GEO || '').split(';');

  // Strip venue name (first segment) from location — keep address only
  const locationRaw = props.LOCATION || null;
  const location = locationRaw ? locationRaw.split(', ').slice(1).join(', ') : null;

  events.push({
    json: {
      title: props.SUMMARY || '',
      description: url ? `See event page: ${url}` : '',
      start_date: start.date,
      start_time: start.time,
      end_date: end.date,
      end_time: end.time,
      location,
      latitude: geo[0] ? parseFloat(geo[0]) : null,
      longitude: geo[1] ? parseFloat(geo[1]) : null,
      url,
      organization: 'Amsterdam Parent Project',
      source: 'luma',
      status: 'new',
      list_id: 'capture'
    }
  });
}

return events;

const scrapedItems = $input.all();
const originalItems = $('Parse iCal').all();

return scrapedItems.map((scraped, i) => {
  const event = originalItems[i].json;
  const jsonLd = scraped.json.metadata?.jsonLd;
  const eventJsonLd = Array.isArray(jsonLd) && jsonLd[0]?.['@type'] === 'Event' ? jsonLd[0] : null;

  const description =
    eventJsonLd?.description ||
    scraped.json.metadata?.description ||
    scraped.json.markdown?.slice(0, 500) ||
    event.description;

  const tagline = description.split('\n')[0];
  const newsletter_description = description;

  // Enrich location data with usual APP hosting spots
  if (event.location === 'Vasco Da Gamastraat 65, 1057 VJ Amsterdam, Netherlands') {
    event.area = 'West';
    event.neighborhood = 'De Baarsjes';
  }
  if (event.location?.includes('Museum')) {
    event.area = 'South';
    event.neighborhood = 'Museumplein';
  }

  return { json: { ...event, description, tagline, newsletter_description } };
});
